    expect(result.current.streamChunks.liveText).toBe('');
    expect(result.current.streamChunks.history.length).toBe(1);
    expect(result.current.streamChunks.history[0]).toMatchObject({
      stepId: 's5',
      stepName: 'Step 5',
      persona: 'ai',
      fullText: 'Hello World',
      tokenCount: 2,
      tokensPerSec: 10,
    });
