    expect(result.current.isComplete).toBe(false);
    expect(result.current.lastError).toBeNull();
    expect(result.current.streamChunks).toMatchObject({
      stepId: null,
      stepName: null,
      persona: null,
      liveText: '',
      tokenCount: 0,
      tokensPerSec: 0,
      history: [],
    });
  });

  it('should handle missing workflowEngine gracefully', () => {
