import { act } from 'react-dom/test-utils'
import { useElementStore } from '../../src/store/useElementStore'

type Element = {
  id: string
  name: string
  symbol: string
}
type ElementCategory = 'metal' | 'nonmetal' | 'metalloid'
type Phase = 'solid' | 'liquid' | 'gas'

describe('useElementStore', () => {
  const sampleElement: Element = { id: '1', name: 'Hydrogen', symbol: 'H' }
  const anotherElement: Element = { id: '2', name: 'Helium', symbol: 'He' }

  beforeEach(() => {
    useElementStore.setState({
      selectedElement: null,
      activeCategory: null,
      activePhase: null,
      searchTerm: '',
    })
  })

  it('should have initial state', () => {
    const state = useElementStore.getState()
    expect(state.selectedElement).toBeNull()
    expect(state.activeCategory).toBeNull()
    expect(state.activePhase).toBeNull()
    expect(state.searchTerm).toBe('')
  })

  it('should select an element', () => {
    act(() => {
      useElementStore.getState().selectElement(sampleElement)
    })
    expect(useElementStore.getState().selectedElement).toEqual(sampleElement)
  })

  it('should clear selected element', () => {
    act(() => {
      useElementStore.getState().selectElement(sampleElement)
      useElementStore.getState().clearSelection()
    })
    expect(useElementStore.getState().selectedElement).toBeNull()
  })

  it('should set active category', () => {
    act(() => {
      useElementStore.getState().setCategory('metal')
    })
    expect(useElementStore.getState().activeCategory).toBe('metal')
  })

  it('should clear active category', () => {
    act(() => {
      useElementStore.getState().setCategory('nonmetal')
      useElementStore.getState().setCategory(null)
    })
    expect(useElementStore.getState().activeCategory).toBeNull()
  })

  it('should set active phase', () => {
    act(() => {
      useElementStore.getState().setPhase('liquid')
    })
    expect(useElementStore.getState().activePhase).toBe('liquid')
  })

  it('should clear active phase', () => {
    act(() => {
      useElementStore.getState().setPhase('gas')
      useElementStore.getState().setPhase(null)
    })
    expect(useElementStore.getState().activePhase).toBeNull()
  })

  it('should set search term', () => {
    act(() => {
      useElementStore.getState().setSearchTerm('helium')
    })
    expect(useElementStore.getState().searchTerm).toBe('helium')
  })

  it('should clear filters', () => {
    act(() => {
      useElementStore.getState().setCategory('metalloid')
      useElementStore.getState().setPhase('solid')
      useElementStore.getState().setSearchTerm('carbon')
      useElementStore.getState().clearFilters()
    })
    const state = useElementStore.getState()
    expect(state.activeCategory).toBeNull()
    expect(state.activePhase).toBeNull()
    expect(state.searchTerm).toBe('')
  })

  it('should handle multiple state changes independently', () => {
    act(() => {
      useElementStore.getState().setCategory('metal')
      useElementStore.getState().setPhase('solid')
      useElementStore.getState().setSearchTerm('iron')
      useElementStore.getState().selectElement(anotherElement)
    })
    const state = useElementStore.getState()
    expect(state.activeCategory).toBe('metal')
    expect(state.activePhase).toBe('solid')
    expect(state.searchTerm).toBe('iron')
    expect(state.selectedElement).toEqual(anotherElement)
  })

  it('should not throw when clearing selection or filters if already null/empty', () => {
    expect(() => {
      act(() => {
        useElementStore.getState().clearSelection()
        useElementStore.getState().clearFilters()
      })
    }).not.toThrow()
    const state = useElementStore.getState()
    expect(state.selectedElement).toBeNull()
    expect(state.activeCategory).toBeNull()
    expect(state.activePhase).toBeNull()
    expect(state.searchTerm).toBe('')
  })
})
